insert into contributions (family_id, person_id, type, field, field_label, title, content, contributor, status, date) values
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'tradition', 'Family Tradition', 'Friday Lakshmi Pooja',
 '{"description":"Every Friday evening, without fail, a small Lakshmi Pooja is done at the house altar — starting with Kamala''s mother-in-law, and never skipped even during travel or illness.","sinceYear":1883,"mediaPath":null}',
 'Kamala Rao', 'Verified', '2026-04-10'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'tradition', 'Family Tradition', 'Deepavali Oil Bath Before Sunrise',
 '{"description":"Everyone in the house bathes in warm sesame oil before sunrise on Deepavali morning, followed by new clothes and the first burst of crackers — exactly as Narasimha''s parents did it in Mangalore.","sinceYear":1935,"mediaPath":null}',
 'Narasimha Rao', 'Verified', '2026-05-02'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'tradition', 'Family Tradition', 'Ugadi Bevu-Bella',
 '{"description":"On Ugadi morning, before anything else is eaten, everyone takes a small mix of neem and jaggery — a reminder that the year ahead holds both bitterness and sweetness.","sinceYear":null,"mediaPath":null}',
 'Saraswathi Rao', 'Verified', '2026-06-14'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'kula_devata', 'Kula Devata Journey', 'Venkateshwara of Tirupati',
 '{"description":"The family''s kula devata is Lord Venkateshwara at Tirupati. Narasimha''s grandfather made the journey on foot as a young man and vowed the family would visit every twelve years — a promise the family still keeps, now by train instead of on foot.","sinceYear":1912,"mediaPath":null}',
 'Narasimha Rao', 'Verified', '2026-04-18'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'sloka', 'Family Sloka', 'Vishnu Sahasranama, every evening',
 '{"description":"Recited together after the evening lamp is lit — Saraswathi learned it from her mother-in-law, who in turn learned it as a girl in Udupi. The grandchildren now recite the first twenty names from memory.","sinceYear":null,"mediaPath":null}',
 'Saraswathi Rao', 'Verified', '2026-05-20'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'festival', 'Festival Through Generations', 'Rama Navami Panaka, then and now',
 '{"description":"Kamala''s generation made panaka in a mud pot and shared it standing at the gate for anyone passing by. Today it''s served in steel tumblers on the veranda, but the recipe — jaggery, dry ginger, and a pinch of pepper — hasn''t changed once.","sinceYear":1908,"mediaPath":null}',
 'Krishnamurthy Rao', 'Verified', '2026-04-05'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'dharma', 'Family Dharma', 'Guests eat first, always',
 '{"description":"No one in the house sits down to a meal until any guest present has been served — a rule Padmavathi''s mother enforced without exception, even when there was barely enough to go around.","sinceYear":null,"mediaPath":null}',
 'Padmavathi Sharma', 'Verified', '2026-05-28'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'dharma', 'Family Dharma', 'Never sleep without lighting the lamp',
 '{"description":"Someone lights the evening lamp before dark every single day — if everyone is out, a neighbour is asked. It has never gone a night unlit in living memory.","sinceYear":null,"mediaPath":null}',
 'Venkat Sharma', 'Verified', '2026-06-02'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'wisdom', 'Ancestor Wisdom', 'Narasimha Rao',
 '{"description":"Speak less, listen more — you will never regret a word you didn''t say.","sinceYear":null,"mediaPath":null}',
 'Ravindra Rao', 'Verified', '2026-06-10'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'wisdom', 'Ancestor Wisdom', 'Kamala Rao',
 '{"description":"Save before you spend, not after.","sinceYear":null,"mediaPath":null}',
 'Sunanda Rao', 'Verified', '2026-06-15'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'wisdom', 'Ancestor Wisdom', 'Krishnamurthy Rao',
 '{"description":"Education is the one property nobody can ever steal from you.","sinceYear":null,"mediaPath":null}',
 'Anand Sharma', 'Verified', '2026-06-22'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'lost_skill', 'Lost Skill', 'Yakshagana Makeup Artistry',
 '{"description":"Narasimha''s own father was known across two villages for his Yakshagana face-painting — a skill nobody in the family carried forward after he passed. A few of his brushes are still kept, unused, in the old trunk.","sinceYear":null,"mediaPath":null}',
 'Narasimha Rao', 'Verified', '2026-06-28'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'memory', 'Living Memory', 'What Kamala Never Wants Forgotten',
 '{"description":"That we never had much money, but we never once turned away someone who was hungry. If you remember nothing else about this family, remember that.","sinceYear":null,"mediaPath":null}',
 'Kamala Rao', 'Verified', '2026-07-01'),
('00000000-0000-0000-0000-000000000001', null, 'parampara', 'lineage', 'Veda Lineage', 'Family lineage',
 '{"gotra":"Bharadwaja","pravara":"Bharadwaja, Angirasa, Barhaspatya","veda":"Yajurveda","shakha":"Taittiriya","guru":"Sringeri Sharada Peetham","generations":"Traced back 6 generations to Mangalore"}',
 'Narasimha Rao', 'Verified', '2026-04-01');
